# Minimal in-memory stand-in for the Redis commands ActiveSupport's
# RedisCacheStore issues for increment/read_multi. Honors TTLs via Time.now
# (so travel_to works) and returns values as strings, like real Redis.
class FakeRedis
  attr_reader :data, :expires

  def initialize
    @data = {}
    @expires = {}
  end

  def info(*)
    { "redis_version" => "7.2.4" }
  end

  def pipelined
    pipe = Pipeline.new(self)
    yield pipe
    pipe.run
  end

  def incrby(key, amount)
    live!(key)
    @data[key] = (@data.fetch(key, "0").to_i + amount).to_s
    @data[key].to_i
  end

  def expire(key, seconds, condition = nil)
    live!(key)
    return 0 unless @data.key?(key)
    return 0 if condition == "NX" && @expires.key?(key)
    @expires[key] = Time.now + seconds
    1
  end

  def ttl(key)
    live!(key)
    return -2 unless @data.key?(key)
    return -1 unless @expires.key?(key)
    (@expires[key] - Time.now).ceil
  end

  def mget(*keys)
    keys.map { |k| live!(k); @data[k] }
  end

  def get(key)
    live!(key)
    @data[key]
  end

  private
    def live!(key)
      return unless @expires.key?(key) && Time.now >= @expires[key]
      @data.delete(key)
      @expires.delete(key)
    end

    class Pipeline
      def initialize(redis)
        @redis = redis
        @queue = []
      end

      def incrby(*args) = @queue << [:incrby, args]
      def ttl(*args) = @queue << [:ttl, args]
      def call(cmd, *args) = @queue << [cmd, args]

      def run
        @queue.map { |cmd, args| @redis.public_send(cmd, *args) }
      end
    end
end
EOF
