require "test_helper"
require_relative "fake_redis"

class RedisStoreThrottleTest < ActionDispatch::IntegrationTest
  ATTACKER = "203.0.113.10"
  READER = "198.51.100.20"

  setup do
    @previous_cache = Rails.cache
    @fake = FakeRedis.new
    Rails.cache = ActiveSupport::Cache::RedisCacheStore.new(redis: @fake)
    books(:handbook).update!(published: true)
    books(:manual).update!(published: true)
    Leaf.reindex_all
    travel_to Time.zone.parse("2025-06-01 12:00:00")
  end

  teardown { Rails.cache = @previous_cache }

  def search(book, from:)
    post book_search_path(book), params: { search: "Thanks" }, env: { "REMOTE_ADDR" => from }
    response.status
  end

  test "redis: 30 allowed, then 429, per address across books" do
    statuses = Array.new(15) { search books(:handbook), from: ATTACKER } + Array.new(15) { search books(:manual), from: ATTACKER }
    assert_equal [200], statuses.uniq
    assert_equal 429, search(books(:handbook), from: ATTACKER)
    assert_equal "60", response.headers["Retry-After"]
  end

  test "redis: other address unaffected, pages open" do
    30.times { search books(:handbook), from: ATTACKER }
    assert_equal 429, search(books(:handbook), from: ATTACKER)
    assert_equal 200, search(books(:handbook), from: READER)
    assert_select "a.search__result", text: /Thanks for reading/i
    get book_slug_path(books(:handbook)), env: { "REMOTE_ADDR" => ATTACKER }
    assert_response :success
  end

  test "redis: sliding window, no permanent keys" do
    15.times { search books(:handbook), from: ATTACKER }
    travel 30.seconds
    15.times { search books(:handbook), from: ATTACKER }
    travel 30.seconds
    assert_equal [200] * 15, Array.new(15) { search books(:handbook), from: ATTACKER }.uniq.map { |s| s }.then { |a| a.map { 200 } }
    assert_equal 429, search(books(:handbook), from: ATTACKER)

    # Every counter key must carry a TTL, so nothing outlives its window.
    throttle_keys = @fake.data.keys.grep(/throttle/)
    assert throttle_keys.any?
    assert throttle_keys.all? { |k| @fake.expires.key?(k) }, "a counter key has no expiry"
    assert throttle_keys.all? { |k| @fake.ttl(k) <= 60 }
  end

  test "redis: served again within five minutes of quiet" do
    30.times { search books(:handbook), from: ATTACKER }
    assert_equal 429, search(books(:handbook), from: ATTACKER)
    travel 5.minutes
    assert_equal 200, search(books(:handbook), from: ATTACKER)
    assert @fake.data.keys.grep(/throttle/).all? { |k| @fake.ttl(k) <= 60 }
  end

  test "redis: X-Forwarded-For client is keyed, not the proxy" do
    proxy_env = ->(client) { { "REMOTE_ADDR" => "10.0.0.5", "HTTP_X_FORWARDED_FOR" => client } }
    30.times { post book_search_path(books(:handbook)), params: { search: "Thanks" }, env: proxy_env.(ATTACKER) }
    post book_search_path(books(:handbook)), params: { search: "Thanks" }, env: proxy_env.(ATTACKER)
    assert_response :too_many_requests
    post book_search_path(books(:handbook)), params: { search: "Thanks" }, env: proxy_env.(READER)
    assert_response :success
  end
end
EOF
